(function(){
  'use strict';
  const P=window.Planning;
  const kinds=['Связь','ТВ и кино','ИИ','Музыка','Другое'];
  const kindIcons={'Связь':'↗','ТВ и кино':'▷','ИИ':'✧','Музыка':'♫','Другое':'↻'};
  const formatDay=d=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'));
  const currency=n=>`<span class="sensitive">${money(n)}</span>`;
  function ensureState(){
    if(!state.play)state.play={checkins:[],claims:[],visits:[],goalEvents:[]};
    if(!state.plan)state.plan={paydayDay:1,salary:650000,available:null,reserve:0,daily:null,incoming:650000,needsPct:50,savingsPct:20,horizon:60,risk:'medium'};
    if(!state.subscriptions)state.subscriptions=[['Beeline • мобильная связь',5990,'Связь',1,'kaspi'],['TV+ • фильмы и передачи',2990,'ТВ и кино',3,'halyk'],['ChatGPT Plus',10900,'ИИ',5,'freedom'],['Claude Pro',10900,'ИИ',8,'freedom'],['Spotify',2190,'Музыка',12,'kaspi']].map(([name,amount,kind,offset,account])=>{const nextDate=P.addDays(localDate(),offset);return {id:uid(),name,amount,kind,nextDate,anchorDay:Number(nextDate.slice(8)),cycle:'monthly',active:true,account,demo:true};});
    state.goals.forEach(g=>{if(g.monthly===undefined)g.monthly=0;if(g.deadline===undefined)g.deadline='';});
  }
  function currentForecast(){ensureState();const p=state.plan;return P.forecast({today:localDate(),paydayDay:p.paydayDay,balance:p.available===null?totalBalance():p.available,reserve:p.reserve,daily:p.daily===null?P.dailyEstimate(state.transactions,state.subscriptions,localDate()):p.daily,subscriptions:state.subscriptions});}
  function upcoming(limit=6){return P.occurrences(state.subscriptions,localDate(),P.addDays(localDate(),30)).slice(0,limit);}
  function billingRows(rows,withActions=false){return rows.map(s=>`<div class="billing-row"><span class="service-icon">${kindIcons[s.kind]||'↻'}</span><div class="billing-info"><strong>${esc(s.name)}</strong><small>${s.overdue?'Просрочено · ':''}${formatDay(s.date)} · ${esc(s.kind)}</small></div><strong class="sensitive ${s.overdue?'danger-text':''}">${money(s.amount)}</strong>${withActions?`<button class="button secondary compact" data-pay-sub="${esc(s.id)}" data-due-date="${s.date}">Учесть оплату</button>`:''}</div>`).join('')||'<div class="empty">В ближайшие 30 дней списаний нет.</div>';}
  function dashboard(){const f=currentForecast(),a=gameState(),rows=upcoming(3);return `<div class="growth-dashboard"><section class="panel forecast-mini"><div class="panel-head"><div><h2 class="panel-title">Хватит до зарплаты?</h2><p class="panel-subtitle">До ${formatDay(f.payday)} · ${f.days} дн.</p></div><span class="status-tag ${f.shortfall?'warning':''}">${f.shortfall?'Нужен план':'В пределах плана'}</span></div><div class="panel-body"><div class="forecast-mini-value sensitive ${f.endBalance<0?'danger-text':''}">${money(f.endBalance)}</div><p class="panel-subtitle">Прогноз перед зарплатой при расходах ${money(f.daily)}/день</p><div class="mini-divider"></div><div class="growth-inline"><span>Ориентир на день</span><strong class="sensitive">${money(f.safeDaily)}</strong></div><button class="link-button" data-page="forecast">Настроить прогноз ↗</button></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Ближайшие списания</h2><p class="panel-subtitle">Связь, ТВ и ваши сервисы · следующие 30 дней</p></div><button class="link-button" data-page="subscriptions">Все ↗</button></div><div class="billing-list dashboard-bills">${billingRows(rows)}</div></section><section class="panel progress-mini"><div class="panel-head"><h2 class="panel-title">Ваш финансовый уровень</h2><span>✦</span></div><div class="panel-body"><div class="level-title">${esc(a.level.name)}</div><p class="panel-subtitle">${a.xp} XP · открыто ${a.badges.filter(b=>b.earned).length} из ${a.badges.length}</p><div class="progress"><div style="width:${a.nextLevel?(a.xp-a.level.min)/(a.nextLevel.min-a.level.min)*100:100}%"></div></div><button class="link-button" data-page="achievements">Коллекция достижений ↗</button></div></section></div>`;}
  function forecastChart(f){const values=[f.available,...f.points.map(p=>p.balance)],min=Math.min(0,...values),max=Math.max(1,...values),scale=v=>20+(max-v)/(max-min||1)*140,x=i=>42+i/(values.length-1||1)*650,points=values.map((v,i)=>`${x(i)},${scale(v)}`).join(' ');return `<div class="forecast-chart"><svg viewBox="0 0 735 210" role="img" aria-label="Прогноз остатка: от ${money(f.available)} до ${money(f.endBalance)} перед зарплатой"><line x1="42" x2="700" y1="${scale(0)}" y2="${scale(0)}" stroke="var(--muted)" stroke-dasharray="4 5"/><text x="4" y="${scale(0)+4}">0 ₸</text><polyline points="${points}" fill="none" stroke="${f.shortfall?'#c37d6f':'#77995b'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${scale(v)}" r="3" fill="${v<0?'#c37d6f':'#77995b'}"><title>${i?formatDay(f.points[i-1].date):'Начальный остаток'}: ${money(v)}</title></circle>`).join('')}<text x="42" y="196">Сегодня</text><text x="700" y="196" text-anchor="end">До ${esc(formatDay(f.payday))}</text></svg></div>`;}
  function forecast(){const f=currentForecast(),p=state.plan,estimated=P.dailyEstimate(state.transactions,state.subscriptions,localDate());return heading('Спокойно до зарплаты.','Посмотрите будущий остаток до следующего поступления.',`<button class="button primary" data-growth="plan-settings">⚙ Настроить прогноз</button>`)+`<div class="welcome-banner"><span class="sparkle">◷</span><span>Прогноз на <strong>${f.days} дн.</strong> до ${formatDay(f.payday)}. ${f.shortfall?'При текущем сценарии деньги могут закончиться '+formatDay(f.shortfall)+'.':'При текущем сценарии остаток остаётся положительным.'}</span></div><div class="stats">${stat('Доступно с учётом резерва',f.available,p.available===null?'Остаток всех счетов минус резерв':'Введённая сумма минус резерв','◈',true)}${stat('Подписки до зарплаты',f.bills,'Активные и неоплаченные','↻')}${stat('Остаток перед зарплатой',f.endBalance,'После повседневных трат и подписок','◷')}${stat('Ориентир на день',f.safeDaily,'Если распределить доступное поровну','↗')}</div><div class="planning-columns"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Как меняется остаток</h2><p class="panel-subtitle">Зарплата не включена: график заканчивается накануне</p></div><span class="status-tag ${f.shortfall?'warning':''}">${f.shortfall?'Возможен дефицит':'Баланс устойчив'}</span></div><div class="panel-body">${forecastChart(f)}<div class="forecast-explanation"><span>Ежедневные расходы: <strong>${money(f.daily)}</strong></span><span>Ожидаемая зарплата: <strong>${money(p.salary)}</strong></span></div></div></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Что заложено в расчёт</h2></div><div class="panel-body"><div class="info-box">${p.daily===null?'Повседневный расход рассчитан по доступной истории последних 90 дней: '+money(estimated)+' в день.':'Вы задали повседневный расход вручную.'}<br>Отдельно добавлены активные подписки. Записи, отмеченные как оплаченные подписки, исключены из среднего, чтобы не считать их дважды.<br>Другие обязательные платежи включите в ежедневную сумму или добавьте как регулярный платёж.</div><p class="notice">Это сценарный расчёт, а не гарантия остатка. Будущие изменения доходов, цен и курсов не учитываются. Базовые настройки и подписки — демонстрационные, замените их своими.</p></div></section></div><section class="panel section-gap"><div class="panel-head"><h2 class="panel-title">Списания до зарплаты</h2><button class="link-button" data-page="subscriptions">Управлять ↗</button></div><div class="billing-list">${billingRows(P.occurrences(state.subscriptions,localDate(),P.addDays(f.payday,-1)),true)}</div></section>`;}
  function subscriptions(){const subs=state.subscriptions,cost=P.monthlyCost(subs),rows=upcoming(100),near=rows.filter(s=>s.effectiveDate<=P.addDays(localDate(),7)).reduce((sum,s)=>sum+s.amount,0);return heading('Подписки без сюрпризов.','Связь, телепередачи, фильмы, музыка и ИИ — в одном календаре.',`<button class="button primary" data-growth="add-subscription">＋ Добавить платёж</button>`)+`<div class="welcome-banner"><span class="sparkle">↻</span><span><strong>Демо-примеры, не действующие тарифы.</strong> Названия и суммы сервисов можно изменить. Автосписание денег и банковская синхронизация не выполняются.</span></div><div class="stats">${stat('В среднем за месяц',cost,'Годовые платежи разделены на 12','↻',true)}${stat('За год',cost*12,'При сохранении текущих цен','◷')}${stat('В следующие 7 дней',near,'Планируемые списания, включая сегодня','↓')}${stat('Активных сервисов',subs.filter(s=>s.active).length,'Подписки и регулярные платежи','✧').replace('₸</span>','шт.</span>')}</div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Календарь ближайших списаний</h2><p class="panel-subtitle">Следующие 30 дней · просроченные платежи показаны первыми</p></div></div><div class="billing-list">${billingRows(rows,true)}</div></section><div class="subscription-grid section-gap">${subs.map(s=>`<article class="panel subscription-card ${s.active?'':'paused'}"><div class="subscription-card-top"><span class="service-icon">${kindIcons[s.kind]}</span><span class="status-tag">${s.active?'Активна':'На паузе'}</span></div><h3>${esc(s.name)}</h3><p class="muted">${esc(s.kind)} · ${accounts[s.account].name}</p><div class="subscription-price sensitive">${money(s.amount)} <small>/ ${s.cycle==='yearly'?'год':'мес.'}</small></div><p class="subscription-date">Следующая оплата: ${formatDay(s.nextDate)}</p><div class="subscription-actions"><button class="button secondary" data-edit-sub="${esc(s.id)}">Изменить</button><button class="button secondary" data-toggle-sub="${esc(s.id)}">${s.active?'Пауза':'Возобновить'}</button><button class="icon-button" data-remove-sub="${esc(s.id)}" aria-label="Удалить подписку ${esc(s.name)}">×</button></div></article>`).join('')||'<div class="panel empty">Добавьте первую подписку или регулярный платёж.</div>'}</div><p class="notice">«Пауза» отключает подписку только в расчётах Cashual. Отмена услуги выполняется у провайдера. «Учесть оплату» создаёт расход в истории, но не отправляет платёж.</p>`;}
  function goalDetails(g){const projection=P.goalProjection(g,localDate()),needed=g.deadline&&g.deadline>localDate()?Math.max(1,Math.ceil(P.daysBetween(localDate(),g.deadline)/30.4375)):null,required=needed?Math.ceil(Math.max(0,g.target-g.saved)/needed):null;return `<div class="goal-plan"><span class="eyebrow">Когда получится?</span><strong>${projection.months===0?'Цель достигнута':projection.date?formatDay(projection.date):projection.months?'Горизонт больше 100 лет':'Задайте ежемесячный взнос'}</strong><p>${g.monthly?money(g.monthly)+' / месяц · '+(projection.months||0)+' взносов':'Без ожидаемой инвестиционной доходности'}</p>${g.deadline?`<p>Желаемый срок: ${formatDay(g.deadline)}${required!==null?' · ориентир '+money(required)+'/мес.':g.saved<g.target?' · срок наступил':''}</p>`:''}<button class="link-button" data-goal-plan="${esc(g.id)}">Настроить взнос и срок ↗</button></div>`;}
  function advice(){const p=state.plan,alloc=P.allocation(p.incoming,p.needsPct,p.savingsPct),daily=P.dailyEstimate(state.transactions,state.subscriptions,localDate()),monthly=daily*30+P.monthlyCost(state.subscriptions),reserveTarget=monthly*3;return heading('У каждого тенге — своя задача.','Распределите поступление и выберите следующий шаг к устойчивости.',`<button class="button primary" data-growth="allocation-settings">⚙ Мой план</button>`)+`<div class="allocation-hero panel"><div><div class="eyebrow">План для поступления</div><div class="allocation-total sensitive">${money(p.incoming)}</div><p class="muted">Шаблон ${p.needsPct}/${100-p.needsPct-p.savingsPct}/${p.savingsPct}: обязательное / свободное / накопления</p></div><button class="button secondary" data-growth="use-income">Взять последний доход ↙</button></div><div class="allocation-grid section-gap">${[['Обязательное',alloc.needs,p.needsPct,'Связь, жильё, продукты и необходимые платежи.','01'],['Свободные траты',alloc.wants,100-p.needsPct-p.savingsPct,'Отдых, удовольствия и необязательные сервисы.','02'],['В будущее',alloc.savings,p.savingsPct,'Резерв, цели и долгосрочные планы.','03']].map(([title,value,pct,text,n])=>`<article class="panel allocation-card"><div class="growth-inline"><span class="eyebrow">${n} / ${title}</span><span class="status-tag">${pct}%</span></div><strong class="allocation-value sensitive">${money(value)}</strong><p>${text}</p><div class="progress"><div style="width:${pct}%"></div></div></article>`).join('')}</div><p class="notice">Это редактируемый учебный шаблон, а не универсальная норма. Деньги не переводятся автоматически. Если обязательных расходов больше, сначала скорректируйте доли.</p><div class="advice-grid section-gap"><article class="panel advice-card"><span class="advice-number">01</span><h2>Сначала — запас спокойствия</h2><p>Ориентир для планирования: несколько месяцев необходимых расходов. Начните с достижимой суммы и постепенно увеличивайте резерв.</p><div class="advice-callout">Иллюстрация: 3 × ${money(monthly)} ≈ <strong class="sensitive">${money(reserveTarget)}</strong></div><p class="notice">Расчёт использует все средние повседневные траты и подписки. Уточните необходимые расходы под свою ситуацию; это не персональный норматив.</p><button class="link-button" data-growth="reserve-goal">Создать цель «Резерв» ↗</button></article><article class="panel advice-card"><span class="advice-number">02</span><h2>Сбережения под срок цели</h2><p>${p.horizon<=12?'Вы выбрали срок до года. Для денег, которые скоро понадобятся, изучите ликвидные сберегательные инструменты и условия депозита: доступ к деньгам, комиссии и ограничения снятия.':'Для целей с запасом времени сравните условия сберегательных инструментов: срок, доступ к деньгам, валюту будущих расходов, комиссии и риски.'}</p><p>Сравнивайте итоговую доходность после расходов, а не только рекламную ставку. Проверьте условия защиты вкладов у местного регулятора.</p><button class="link-button" data-page="goals">Посмотреть сроки моих целей ↗</button></article><article class="panel advice-card"><span class="advice-number">03</span><h2>Инвестиции — после подготовки</h2><p>${p.risk==='low'?'Вы отметили низкую готовность к потерям. Изучите консервативные инструменты и их риски; даже облигации и фонды не гарантируют сохранение капитала.':p.horizon<60?'При коротком горизонте колебания рынка могут помешать цели. Отделите деньги ближайших лет от средств, которые готовы инвестировать надолго.':'Для долгого горизонта изучите диверсифицированные фонды, облигации и распределение между классами активов. Оцените комиссии, валютный риск и возможные потери.'}</p><p>Не вкладывайте резерв в активы, которые придётся срочно продавать при падении. Не полагайтесь на обещания гарантированной высокой доходности.</p><a class="link-button" href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation" target="_blank" rel="noopener noreferrer">О сроке, риске и диверсификации ↗</a></article><article class="panel advice-card"><span class="advice-number">04</span><h2>Найдите деньги в привычках</h2><p>Активные сервисы обходятся примерно в <strong class="sensitive">${money(P.monthlyCost(state.subscriptions)*12)} в год</strong>. Оставьте те, которыми пользуетесь, и рассмотрите отмену остальных у провайдера.</p><p>Экономию можно направить в цель: уменьшите регулярный расход и увеличьте ежемесячный взнос, чтобы увидеть новую дату достижения.</p><button class="link-button" data-page="subscriptions">Проверить мои сервисы ↗</button></article></div><div class="info-box section-gap"><strong>Образовательные подсказки, не подбор ценных бумаг.</strong><br>Горизонт в настройках: ${p.horizon} мес.; готовность к риску: ${{low:'низкая',medium:'умеренная',high:'высокая'}[p.risk]}. Доходность не обещается. Общие принципы срока и диверсификации: <a href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation" target="_blank" rel="noopener noreferrer">Investor.gov</a>.</div>`;}
  let badgeFilter='all',badgeGroup='all';
  function gameState(){return P.achievements({goals:state.goals,transactions:state.transactions,month:currentMonth,subscriptions:state.subscriptions,budgets:state.budgets,today:localDate(),play:state.play});}
  function recordVisit(next){if(!state.play||!['forecast','budgets','goals','advice','subscriptions'].includes(next))return;if(!state.play.visits.some(v=>v.date===localDate()&&v.page===next)){state.play.visits.push({date:localDate(),page:next});persist();}}
  function recordGoalContribution(goalId,amount){ensureState();state.play.goalEvents.push({date:localDate(),goalId,amount});}
  function achievementCard(b){if(window.CashualRewards)return window.CashualRewards.badgeCard(b);const text=b.unit==='₸'?money(Math.max(0,b.target-b.current)):b.unit==='%'?Math.max(0,b.target-b.current).toFixed(1)+' п.п.':Math.max(0,b.target-b.current)+' '+b.unit;const progress=b.unit==='₸'?money(b.current)+' / '+money(b.target):b.unit==='%'?b.current.toFixed(1)+'% / '+b.target+'%':Math.min(b.current,b.target)+' / '+b.target+(b.unit?' '+b.unit:'');return '<article class="panel achievement-card '+b.tier+' '+(b.earned?'earned':'locked')+'"><div class="growth-inline"><span class="status-tag">'+({bronze:'Бронза',silver:'Серебро',gold:'Золото',legendary:'Легенда'}[b.tier])+'</span><span class="badge-xp">＋'+b.xp+' XP</span></div><div class="badge-medal">'+b.symbol+'</div><span class="badge-group-label">'+esc(b.group)+'</span><h3>'+esc(b.title)+'</h3><p>'+esc(b.description)+'</p><div class="badge-progress-label">'+progress+'</div><div class="progress"><div style="width:'+b.progress*100+'%"></div></div><div class="badge-status">'+(b.earned?'✓ Получено':b.target===1?'◇ Ещё не получено':'Осталось: '+text)+'</div>'+(!b.earned?'<div class="badge-next-step"><strong>Как получить</strong><span>'+esc(b.description)+'</span></div>':'')+'</article>';}
  function achievements(){const a=gameState(),earned=a.badges.filter(b=>b.earned),locked=a.badges.filter(b=>!b.earned),checked=state.play.checkins.includes(localDate()),groups=[...new Set(a.badges.map(b=>b.group))],shown=a.badges.filter(b=>(badgeFilter==='all'||(badgeFilter==='earned'?b.earned:!b.earned))&&(badgeGroup==='all'||b.group===badgeGroup));const next=locked.filter(b=>b.threshold).at(0);return heading('Твой прогресс. Твои награды.','50 достижений, ежедневные задания и привычки, которые работают.', '<button class="button '+(checked?'secondary':'primary')+'" data-game="checkin" '+(checked?'disabled':'')+'>'+(checked?'✓ День отмечен':'✦ Отметить день · +10 XP')+'</button>')+
    '<section class="achievement-hero"><div><div class="eyebrow">Уровень '+(a.nextLevel?a.level.min===0?1:({150:2,400:3,800:4,1400:5,2200:6,3400:7,5000:8}[a.level.min]||1):9)+' · '+a.xp+' XP</div><h2>'+esc(a.level.name)+'</h2><p>'+(a.nextLevel?'До уровня «'+esc(a.nextLevel.name)+'» осталось '+(a.nextLevel.min-a.xp)+' XP.':'Максимальный уровень открыт. Продолжайте поддерживать привычки.')+'</p><div class="progress"><div style="width:'+(a.nextLevel?(a.xp-a.level.min)/(a.nextLevel.min-a.level.min)*100:100)+'%"></div></div></div><div class="achievement-emblem">✦</div></section>'+
    '<div class="game-metrics"><div><span>Полученные награды</span><strong>'+earned.length+' <small>/ 50</small></strong></div><div><span>Текущая серия</span><strong>'+a.streak.current+' <small>дн.</small></strong></div><div><span>Лучшая серия</span><strong>'+a.streak.longest+' <small>дн.</small></strong></div><div><span>Накопления по целям</span><strong class="sensitive">'+money(a.saved)+'</strong></div></div>'+
    '<section class="panel daily-panel"><div class="panel-head"><div><h2 class="panel-title">Три маленьких шага на сегодня</h2><p class="panel-subtitle">'+formatDay(localDate())+' · задания обновляются каждый календарный день</p></div><span class="status-tag">'+a.missions.filter(m=>m.claimed).length+' / 3</span></div><div class="daily-missions">'+a.missions.map(m=>'<article class="daily-mission '+(m.claimed?'claimed':'')+'"><div class="growth-inline"><span class="mission-icon">'+(m.claimed?'✓':m.ready?'✦':'◇')+'</span><span class="badge-xp">＋'+m.xp+' XP</span></div><h3>'+m.title+'</h3><p>'+m.description+'</p>'+(m.claimed?'<span class="mission-complete">✓ Награда получена</span>':m.ready?'<button class="button primary" data-claim-mission="'+m.id+'">Забрать +'+m.xp+' XP</button>':'<button class="button secondary" data-page="'+m.page+'">Выполнить ↗</button>')+'</article>').join('')+'</div></section>'+
    '<div class="collection-heading"><div><div class="eyebrow">Ваша коллекция</div><h2>'+({all:'Все 50 достижений',earned:'Уже получены',locked:'Ещё впереди'}[badgeFilter])+'</h2></div><div class="achievement-tabs" role="group" aria-label="Статус достижений">'+[['all','Все',50],['earned','Получены',earned.length],['locked','Ещё впереди',locked.length]].map(([id,label,count])=>'<button data-badge-filter="'+id+'" aria-pressed="'+(badgeFilter===id)+'" class="'+(badgeFilter===id?'active':'')+'">'+label+' <span>'+count+'</span></button>').join('')+'</div></div>'+
    '<div class="collection-toolbar"><select class="input" id="badge-group" aria-label="Группа достижений"><option value="all">Все группы</option>'+groups.map(g=>'<option '+(g===badgeGroup?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select><span class="muted">Показано '+shown.length+' · '+a.badgeXP+' XP за награды + '+a.habitXP+' XP за привычки</span></div><div class="achievement-grid">'+(shown.map(achievementCard).join('')||'<div class="panel empty">В этой группе пока нет таких достижений. Посмотрите «Ещё впереди» — там указан следующий шаг.</div>')+'</div>'+
    '<section class="panel section-gap"><div class="panel-head"><h2 class="panel-title">Прозрачные правила игры</h2></div><div class="panel-body"><div class="info-box"><strong>Награды за действия, а не за покупки.</strong> Для учёта подписок не нужно подключать новые платные сервисы. Ежедневные задания по 25 XP можно забрать только один раз за день, отметка дня даёт 10 XP один раз. День определяется по календарю устройства; серия сохраняется до конца следующего дня.<br>Достижения за капитал используют сумму накопленного по целям. Не дублируйте одни деньги между целями. «Финансовая грамотность» сравнивает остаток доходов и расходы текущего месяца: '+money(a.income)+' − '+money(a.expense)+' = '+money(a.surplus)+'.<br>Статус полученных наград и XP за них пересчитываются по текущим данным; изменение целей и новый месяц могут изменить доступные награды. XP за отмеченные дни и забранные задания сохраняются. Все данные локальные, включая демопримеры; банковского подтверждения нет.</div></div></section>';}
  function numberField(label,name,value,{min=0,max=1e9,step='.01'}={}){return field(label,`<input class="input" name="${name}" type="number" min="${min}" max="${max}" step="${step}" value="${value??''}" required>`);}
  function planSettings(){const p=state.plan;openModal('Мой прогноз до зарплаты',numberField('День зарплаты (1–31)','paydayDay',p.paydayDay,{min:1,max:31,step:'1'})+numberField('Ожидаемая зарплата, ₸','salary',p.salary)+field('Доступные деньги, ₸ · пусто = сумма счетов',`<input class="input" name="available" type="number" min="-1000000000" max="1000000000" step=".01" value="${p.available??''}">`)+numberField('Неприкосновенный резерв, ₸','reserve',p.reserve)+field('Повседневные траты в день, ₸ · пусто = история',`<input class="input" name="daily" type="number" min="0" max="1000000000" step=".01" value="${p.daily??''}">`)+'<p class="notice">Зарплата прогнозируется на ближайшую будущую дату. Если день отсутствует в месяце, используется последний день. Резерв вычитается из доступных денег.</p>',data=>{const next={...p,paydayDay:Number(data.get('paydayDay')),salary:Number(data.get('salary')),available:data.get('available')===''?null:Number(data.get('available')),reserve:Number(data.get('reserve')),daily:data.get('daily')===''?null:Number(data.get('daily'))};P.validateExtension({...state,plan:next});state.plan=next;toast('Прогноз обновлён');});}
  function subscriptionModal(id){const s=state.subscriptions.find(x=>x.id===id);openModal(s?'Изменить регулярный платёж':'Добавить подписку или тариф',field('Название сервиса',`<input class="input" name="name" required maxlength="100" value="${esc(s?.name||'')}" placeholder="Например, мобильная связь или ИИ">`)+field('Тип сервиса',`<select class="input" name="kind">${options(kinds,s?.kind)}</select>`)+numberField('Сумма списания, ₸','amount',s?.amount,{min:.01})+field('Периодичность',`<select class="input" name="cycle"><option value="monthly">Каждый месяц</option><option value="yearly" ${s?.cycle==='yearly'?'selected':''}>Каждый год</option></select>`)+field('Ближайшая дата списания',`<input class="input" name="nextDate" type="date" min="2000-01-01" max="2100-12-31" required value="${s?.nextDate||localDate()}">`)+field('Счёт для учёта',`<select class="input" name="account">${Object.entries(accounts).map(([key,a])=>`<option value="${key}" ${key===s?.account?'selected':''}>${a.name}</option>`).join('')}</select>`),data=>{const next={id:s?.id||uid(),name:data.get('name').trim(),kind:data.get('kind'),amount:Number(data.get('amount')),cycle:data.get('cycle'),nextDate:data.get('nextDate'),anchorDay:Number(data.get('nextDate').slice(8)),active:s?.active??true,account:data.get('account'),demo:false};P.validateExtension({...state,subscriptions:[next]});if(s)Object.assign(s,next);else state.subscriptions.push(next);toast('Регулярный платёж сохранён');});}
  function allocationSettings(){const p=state.plan;openModal('Распределение поступления',numberField('Сумма поступления, ₸','incoming',p.incoming)+numberField('Обязательные расходы, %','needsPct',p.needsPct,{max:100,step:'1'})+numberField('Накопления и цели, %','savingsPct',p.savingsPct,{max:100,step:'1'})+numberField('Горизонт цели, месяцев','horizon',p.horizon,{min:1,max:600,step:'1'})+field('Готовность к инвестиционным потерям',`<select class="input" name="risk"><option value="low" ${p.risk==='low'?'selected':''}>Низкая</option><option value="medium" ${p.risk==='medium'?'selected':''}>Умеренная</option><option value="high" ${p.risk==='high'?'selected':''}>Высокая</option></select>`)+'<p class="notice">Оставшаяся доля отводится свободным тратам. Сумма двух заданных долей не должна превышать 100%.</p>',data=>{const next={...p,incoming:Number(data.get('incoming')),needsPct:Number(data.get('needsPct')),savingsPct:Number(data.get('savingsPct')),horizon:Number(data.get('horizon')),risk:data.get('risk')};if(next.needsPct+next.savingsPct>100)throw Error('Обязательные расходы и накопления вместе не должны превышать 100%.');P.validateExtension({...state,plan:next});state.plan=next;toast('План распределения сохранён');});}
  function goalPlan(id){const g=state.goals.find(x=>x.id===id);openModal('План цели: '+g.name,numberField('Буду откладывать каждый месяц, ₸','monthly',g.monthly)+field('Желаемая дата (необязательно)',`<input class="input" name="deadline" type="date" min="${localDate()}" max="2100-12-31" value="${esc(g.deadline)}">`)+'<p class="notice">Прогноз предполагает первый взнос через месяц и не учитывает проценты, инфляцию и комиссии.</p>',data=>{const next={...g,monthly:Number(data.get('monthly')),deadline:data.get('deadline')};P.validateExtension({...state,goals:[next]});Object.assign(g,next);toast('Дата достижения пересчитана');});}
  function recordPayment(id,dueDate){const s=state.subscriptions.find(x=>x.id===id);if(!s||!s.active)return;if(dueDate!==s.nextDate){toast('Сначала учтите самый ранний неоплаченный платёж этой подписки.');return;}if(dueDate>localDate()){toast('Эта дата ещё не наступила. Учтите оплату в день списания или позже.');return;}confirmModal('Учесть оплату '+s.name+'?',money(s.amount)+' будет добавлено как расход на сегодня. Это запись в учёте, а не банковский платёж.',()=>{if(!state.transactions.some(t=>t.subscriptionId===id&&t.billingDate===dueDate)){state.transactions.push({id:uid(),merchant:s.name,amount:s.amount,type:'expense',date:localDate(),account:s.account,category:s.kind==='Связь'?'Коммунальные платежи':s.kind==='ТВ и кино'||s.kind==='Музыка'?'Развлечения':'Другое',source:'manual',subscriptionId:id,billingDate:dueDate});}s.nextDate=P.addMonths(s.nextDate,s.cycle==='yearly'?12:1,s.anchorDay);toast('Расход учтён, следующая дата обновлена');},'Учесть расход');}
  document.addEventListener('change',event=>{if(event.target.id==='badge-group'){badgeGroup=event.target.value;render();}});
  document.addEventListener('click',event=>{
    const b=event.target.closest('button');if(!b)return;
    if(b.dataset.badgeFilter){badgeFilter=b.dataset.badgeFilter;render();}
    if(b.dataset.game==='checkin'){ensureState();if(!state.play.checkins.includes(localDate())){state.play.checkins.push(localDate());persist();render();toast('Финансовый день отмечен · +10 XP за привычку');}}
    if(b.dataset.claimMission){const m=gameState().missions.find(m=>m.id===b.dataset.claimMission);if(m?.ready&&!m.claimed){state.play.claims.push({date:localDate(),id:m.id});persist();render();toast('Задание выполнено · +25 XP');}}
  });
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
    const handlers={'plan-settings':planSettings,'add-subscription':()=>subscriptionModal(),'allocation-settings':allocationSettings,'use-income':()=>{const tx=state.transactions.filter(t=>t.type==='income'&&t.date<=localDate()).slice().reverse().sort((a,b)=>b.date.localeCompare(a.date));if(!tx.length){toast('Сначала добавьте поступление в операциях');return;}state.plan.incoming=tx[0].amount;persist();render();toast('План для дохода «'+tx[0].merchant+'»');},'reserve-goal':()=>{const target=Math.max(10000,Math.round((P.dailyEstimate(state.transactions,state.subscriptions,localDate())*30+P.monthlyCost(state.subscriptions))*3));openModal('Цель «Резерв»',numberField('Целевая сумма, ₸','target',target,{min:1})+'<p class="notice">Начальное значение — иллюстрация трёх месяцев средних расходов. Измените его под свои нужды.</p>',data=>{const target=Number(data.get('target'));if(!Number.isFinite(target)||target<=0)throw Error('Введите положительную сумму.');state.goals.push({id:uid(),name:'Резерв спокойствия',target,saved:0,monthly:0,deadline:'',emoji:'◈'});toast('Цель резерва создана');});}};
    if(b.dataset.growth)handlers[b.dataset.growth]?.();
    if(b.dataset.editSub)subscriptionModal(b.dataset.editSub);
    if(b.dataset.goalPlan)goalPlan(b.dataset.goalPlan);
    if(b.dataset.paySub)recordPayment(b.dataset.paySub,b.dataset.dueDate);
    if(b.dataset.toggleSub){const s=state.subscriptions.find(x=>x.id===b.dataset.toggleSub);s.active=!s.active;persist();render();toast(s.active?'Подписка включена в расчёт':'Подписка на паузе в Cashual');}
    if(b.dataset.removeSub)confirmModal('Удалить регулярный платёж?','Платёж исчезнет из календаря и прогноза. Ранее учтённые расходы сохранятся. Подписка у провайдера не отменится.',()=>{state.subscriptions=state.subscriptions.filter(x=>x.id!==b.dataset.removeSub);toast('Регулярный платёж удалён');},'Удалить');
  });
  navItems.splice(1,0,['forecast','До зарплаты','chart'],['subscriptions','Подписки','card'],['advice','План денег','wallet']);navItems.splice(navItems.findIndex(x=>x[0]==='family'),0,['achievements','Достижения','target']);
  window.CashualGrowth={ensureState,recordVisit,recordGoalContribution,dashboard,goalDetails,pages:{forecast,subscriptions,advice,achievements}};
  ensureState();try{P.validateExtension(state);}catch{delete state.plan;delete state.subscriptions;delete state.play;state.goals.forEach(g=>{delete g.monthly;delete g.deadline;});ensureState();}
  const requested=location.hash.slice(1);if(navItems.some(x=>x[0]===requested))page=requested;
  render();persist();
})();
